_VERSES = {
    1: ("fly", None),
    2: ("spider", "It wriggled and jiggled and tickled inside her."),
    3: ("bird", "How absurd to swallow a bird!"),
    4: ("cat", "Imagine that, to swallow a cat!"),
    5: ("dog", "What a hog, to swallow a dog!"),
    6: ("goat", "Just opened her throat and swallowed a goat!"),
    7: ("cow", "I don't know how she swallowed a cow!"),
    8: ("horse", "She's dead, of course!"),
}

_SPIDER = "spider that wriggled and jiggled and tickled inside her"


def _verse(number):
    animal, comment = _VERSES[number]
    lines = [f"I know an old lady who swallowed a {animal}."]
    if comment:
        lines.append(comment)
    if number != 8:
        for prey_number in range(number - 1, 0, -1):
            prey = _SPIDER if prey_number == 2 else _VERSES[prey_number][0]
            lines.append(f"She swallowed the {animal} to catch the {prey}.")
            animal = prey
        lines.append("I don't know why she swallowed the fly. Perhaps she'll die.")
    return lines


def recite(start_verse, end_verse):
    lines = []
    for number in range(start_verse, end_verse + 1):
        if lines:
            lines.append("")
        lines.extend(_verse(number))
    return lines

